components.css:
.ds-strip { font-family: 'Archivo', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif; display: flex; flex-direction: column; align-items: center; min-width: 48px; padding: 4px 6px 5px; border: 1px solid rgba(255,255,255,.1); border-radius: 2px; background: #2b2820; color: #c6c2ae; box-shadow: inset 0 1px 3px rgba(0,0,0,.5), inset 0 -1px 0 rgba(255,255,255,.07); transition: color .24s ease, border-color .24s ease, background-color .24s ease; }
.ds-strip.is-on { color: #8ecbf2; border-color: color-mix(in srgb, #8ecbf2 55%, transparent); background: color-mix(in srgb, #8ecbf2 28%, transparent); transition-duration: .06s; }
.ds-strip-n { font-size: 9.5px; font-weight: 600; font-stretch: 112%; letter-spacing: .1em; opacity: .7; }
.ds-strip-chord { font-size: 14px; font-weight: 700; font-stretch: 104%; }

.ds-dial { font-family: 'Archivo', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif; text-align: center; width: 52px; cursor: ns-resize; touch-action: none; }
.ds-dial-body { fill: #524d40; stroke: #1a1812; stroke-width: 1; }
.ds-dial-track { fill: none; stroke: rgba(0,0,0,.45); stroke-width: 3.5; stroke-linecap: butt; }
.ds-dial-fill { fill: none; stroke: #f0b45c; stroke-width: 3.5; stroke-linecap: butt; }
.ds-dial-pointer { stroke: #f0b45c; stroke-width: 2.5; stroke-linecap: round; }
.ds-dial-label { display: block; margin-top: 5px; font-size: 9.5px; font-weight: 600; font-stretch: 112%; letter-spacing: .1em; text-transform: uppercase; color: #c6c2ae; }
.ds-dial-value { font-size: 11px; color: #f3f1e6; font-variant-numeric: tabular-nums; }

.ds-tab { font-family: 'Archivo', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif; display: flex; align-items: center; gap: 5px; padding: 6px 7px; border: 1px solid rgba(255,255,255,.1); border-radius: 2px; background: #524d40; color: #f3f1e6; font-size: 12px; cursor: pointer; box-shadow: inset 0 1px 0 rgba(255,255,255,.07), inset 0 -1px 0 rgba(0,0,0,.38); }
.ds-tab.is-active { border-color: color-mix(in srgb, #f0b45c 55%, transparent); background: color-mix(in srgb, #f0b45c 28%, transparent); box-shadow: inset 0 1px 3px rgba(0,0,0,.5), inset 0 -1px 0 rgba(255,255,255,.07); }
.ds-tab.is-active .ds-tab-n { color: #f0b45c; }
.ds-tab-name { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.ds-key { font-family: 'Archivo', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif; display: inline-grid; place-items: center; min-width: 34px; height: 24px; padding: 0 6px; border: 1px solid rgba(255,255,255,.1); border-radius: 2px; background: #524d40; color: #f3f1e6; font-size: 11px; font-weight: 700; font-stretch: 108%; box-shadow: inset 0 1px 0 rgba(255,255,255,.07), inset 0 -1px 0 rgba(0,0,0,.38); }
.ds-key-left { border-color: color-mix(in srgb, #8ecbf2 55%, transparent); background: color-mix(in srgb, #8ecbf2 28%, transparent); color: #8ecbf2; }
.ds-key-right { border-color: color-mix(in srgb, #f0b45c 55%, transparent); background: color-mix(in srgb, #f0b45c 28%, transparent); color: #f0b45c; }

.ds-plate { font-family: 'Archivo', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif; padding: 9px 12px 10px; border: 1px solid rgba(255,255,255,.1); border-top-width: 2px; border-radius: 2px; background: #2b2820; box-shadow: inset 0 1px 3px rgba(0,0,0,.5), inset 0 -1px 0 rgba(255,255,255,.07); }
.ds-plate-left { border-top-color: #8ecbf2; background: color-mix(in srgb, #8ecbf2 16%, transparent); }
.ds-plate-left .ds-plate-name { color: #8ecbf2; }
.ds-plate-name { display: block; margin-bottom: 9px; font-size: 9.5px; font-weight: 700; font-stretch: 112%; letter-spacing: .16em; text-transform: uppercase; }
